{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooks a broken skyline of collapsed spires; Mara crouches over a parchment held down by a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "A single-eyed flame flickers inside a battered oil lamp set on the map, casting orange light across Mara's ink-stained sleeve.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox is wound up for scouting.",
      "visual_description": "A small clockwork fox with blue glass eyes stands on the map; a key in its tail turns by itself with a soft tick.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver steps out of a cracked windowpane.",
      "visual_description": "A figure in a clear diving helmet emerges from a leaning shop window as if from water, coat shimmering with reflected broken streetlamps.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets beneath the looming castle gates.",
      "visual_description": "Enormous iron gates twist open above four figures gathered in long shadows; old royal banners hang in tatters above them.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Tin Fox slips past an armored patrol on the wall.",
      "visual_description": "From a rooftop gargoyle's perch, the metal fox watches plumed helmets march in a torchlit line below.",
      "characters": ["tin_fox"]
    },
    {
      руль_number: 0,
      "scene_number": 7,
      "caption": "The oracle lamp refuses the cursed tower's stairs.",
      "visual_description": "A spiral staircase glows sickly green; the lamp's flame-eye narrows and pulls back from the doorway as Mara hesitates.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector at a checkpoint.",
      "visual_description": "A plump official snores against a ledger pillow at a tollgate, stamped papers stuck to his sleeves, a bell ringing unheard beside him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a dragon rumble from a distant ridge.",
      "visual_description": "Smoke rises behind a jagged silhouette of broken rooftops; the Glass Diver shields his helmet's glass from a hot orange glow.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara charts a route through the mirror district.",
      "visual_description": "A narrow alley lined with leaning silvered mirrors; Mara traces a path with her compass while reflections of her ripple oddly.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver dives through a tall window into the keep.",
      "visual_description": "A stained-glass window ripples like a pond as the coated figure plunges in headfirst, scattering colored light across the cobbles.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Tin Fox finds the captive behind a magic door.",
      "visual_description": "A heavy door is carved with shifting runes; the clockwork fox presses its nose to a seam where pale light leaks out.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp speaks the door's true name.",
      "visual_description": "The lamp hovers before the rune-carved door, its flame-eye wide; sigils peel away in curling sparks.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver carries the sleeping tax collector out.",
      "visual_description": "Inside a vaulted chamber, the coated rescuer hoists the snoring official over one shoulder, ledger still clutched in his arms.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "An armored patrol blocks the courtyard exit.",
      "visual_description": "A line of helmets and raised halberds fills an archway; Tin Fox darts between their boots while Mara presses to a pillar.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Mara leads the team across the rooftops toward the bridge.",
      "visual_description": "Four small silhouettes leap between tiled roofs under a bruised purple sky, the river bridge gleaming in the distance.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracking stone bridge.",
      "visual_description": "An old arched bridge fractures behind their heels; the Glass Diver carries the still-snoring tax collector while the lamp lights the way.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "On the far shore, the rescuers look back at the ruined city.",
      "visual_description": "Dawn breaks over distant broken towers; Mara folds her map, Tin Fox sits at her boot, the lamp dims to a sleepy ember, and the tax collector still snores.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector", "glass_diver"]
    }
  ]
}

